// IBM Plex Sans, subsetted, for the PDFs.
//
// pdfmake ships exactly one family — Roboto — and a PDF cannot resolve a
// webfont, so a document that should look like the app has to carry the app's
// typeface with it. Without this the summary you hand to management was set in
// a different face from the tool it came out of.
//
// These are SUBSETS: the full faces are ~218 KB each, cut here to the code
// points the PDF layer promises to render (utils/pdfGlyphs.js `SUPPORTED`).
// The set is DERIVED from that table rather than guessed, so the font and the
// promise cannot drift apart — and the table itself was then regenerated from
// these files, so it promises exactly what they can draw.
//
// Sans only. Plex Mono is not here because pdfmake's `mono` style is defined
// and never applied by any export, and Mono's coverage is narrower than Sans's
// — carrying it would have cost 94 KB and forced the promise down to the
// intersection, which loses modern Greek. `tools/build-pdf-fonts.mjs` will
// generate it the day something needs it.
/* eslint-disable */
export const PlexSans_Regular = '';
export const PlexSans_Bold = '';

export const PLEX_VFS = {
  'PlexSans-Regular.ttf': PlexSans_Regular,
  'PlexSans-Bold.ttf': PlexSans_Bold,
};

// `italics` points at the upright face on purpose: nothing in the exports sets
// `italics: true`, and a third face is 60 KB for nothing.
export const PLEX_FONTS = {
  PlexSans: {
    normal: 'PlexSans-Regular.ttf',
    bold: 'PlexSans-Bold.ttf',
    italics: 'PlexSans-Regular.ttf',
    bolditalics: 'PlexSans-Bold.ttf',
  },
};
